# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def _shift(name, start, end):
    return Shift(name, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [_shift("Ann", 540, 600), _shift("Bob", 540, 750), _shift("Ann", 700, 760)]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Bob: 1 shifts, 3.5 hours", "Ann: 2 shifts, 2.0 hours"]
        )

    def test_empty(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([_shift("  ", 540, 600)])
